<template><div class="finance-modal" @click.self="$emit('close')"><section class="finance-dialog" role="dialog" aria-modal="true" aria-label="Enable Finance Operations"><header><h2>Enable Finance Operations</h2><button @click="$emit('close')" aria-label="Close setup">×</button></header><p>Enable a financial workspace for an existing organization. Managing organizations receive finance oversight; sponsored organization admins receive the program portal.</p><p v-if="error" role="alert">{{ error }}</p><form @submit.prevent="save"><label>Organization<select v-model="agencyId" required><option value="">Select organization</option><option v-for="o in choices" :key="o.id" :value="o.id">{{ o.name }}</option></select></label><label>Managed by<select v-model="managerAgencyId"><option value="">Self-managed</option><option v-for="o in managers.filter(o=>!o.is_demo&&Number(o.agency_id)!==Number(agencyId))" :key="o.agency_id" :value="o.agency_id">{{ o.name }}</option></select></label><p>Bank imports remain off until the organization authorizes them. Setup adds no balances or transactions.</p><button class="primary" :disabled="busy">Enable workspace</button></form></section></div></template>
<script setup>
import {ref,onBeforeUnmount} from 'vue';import api from '../../services/api';
defineProps({managers:Array});const emit=defineEmits(['close','saved']),choices=ref([]),agencyId=ref(''),managerAgencyId=ref(''),error=ref(''),busy=ref(false);let alive=true;onBeforeUnmount(()=>alive=false);
api.get('/finance-operations/setup-options').then(r=>{if(alive)choices.value=r.data.organizations;}).catch(()=>{if(alive)error.value='Organization choices could not be loaded';});
async function save(){busy.value=true;try{await api.post('/finance-operations/setup',{agencyId:agencyId.value,managerAgencyId:managerAgencyId.value||null});if(alive)emit('saved');}catch(e){if(alive)error.value=e.response?.data?.error?.message||'Setup could not complete';}finally{if(alive)busy.value=false;}}
</script>
